const e="Ils nous ont appris à survivre. Nous avons appris à ne plus nous soumettre.",t="Précepte de Koven",n=["Peuple & Lignée","Orcs / Kovraks","Codex #PEU-002"],s=[1,2,11],i="Koven, Badlands, Vieux Monde",a="Force physique, Discipline, Endurance",o="180cm - 220cm",r="75",l="« Guerriers de Koven »",u="Kovraks_icone.jpeg",c="Commun",d=[{title:"Présentation",type:"text",content:"Les Kovraks sont un ancien peuple d'Asun dont le nom est aujourd'hui souvent remplacé par le terme plus courant d'« orcs ». Leur réputation de peuple brutal et guerrier est largement liée aux conflits qu'ils ont traversés et ne reflète pas l'ensemble de leurs sociétés."},{title:"Origines et Naissance de Koven",type:"text",content:"Après la chute des Dragons, les Kovraks subirent la lourde domination et surveillance de Lorus. Leurs rébellions successives donnèrent naissance à une culture de résistance et de discipline militaire, aboutissant à la fondation de Koven."},{title:"Les Kovraks des Badlands",type:"text",content:"Une branche installée dans les Badlands a subi des transformations suite aux catastrophes magiques de la région, devenant ce qu'on appelle les orcs verts."},{title:"Relations avec les autres peuples",type:"politique_list_long",content:[{headline:"Hostile / Rival",title:"Les Valm de Lorus",content:"Le conflit historique avec Lorus constitue la principale tension politique et militaire de la région.",color:"#FF7A5C"},{headline:"Neutre",title:"Les Lythari & Virelith",content:"Partenaires commerciaux ou militaires occasionnels, maintenant une distance prudente.",color:"#C29B38"},{headline:"Amical",title:"Les Vhaerith",content:"Les Kovraks abordent les Vhaerith avec davantage de curiosité que de peur.",color:"#34D399"}]},{title:"Aujourd'hui",type:"text",content:"Koven constitue une puissance militaire majeure du Vieux Monde, fière d'avoir forgé une société indépendante de toute domination extérieure."}],p={citation:e,citation_author:t,tags:n,link_articles:s,class:"Guerrière / Martiale",repart:i,trait:a,height:o,age:r,surname:l,image:u,statut:c,sections:d};export{r as age,e as citation,t as citation_author,p as default,o as height,u as image,s as link_articles,i as repart,d as sections,c as statut,l as surname,n as tags,a as trait};
